application/json.schema:
{
  "title": "Phone validator, invoice PDF and barcode input",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "mode": {
      "title": "Mode",
      "type": "string",
      "enum": [
        "phone_validate",
        "phone_extract",
        "invoice_pdf",
        "receipt_pdf",
        "barcode_svg",
        "pay_uri"
      ],
      "editor": "select",
      "description": "Phone validator (format and region), extract numbers from text, invoice or receipt PDF, barcode SVG, or a payment URI.",
      "default": "phone_validate",
      "prefill": "phone_validate"
    },
    "phone": {
      "title": "Phone number",
      "type": "string",
      "editor": "textfield",
      "description": "For phone_validate. International or national format."
    },
    "phones": {
      "title": "Phone numbers",
      "type": "array",
      "editor": "stringList",
      "items": {
        "type": "string"
      },
      "description": "For phone_validate. One dataset row and $0.001 per number, up to 200. An invalid number still returns a row with valid: false and is charged.",
      "maxItems": 200,
      "prefill": [
        "+1 650-253-0000",
        "+44 20 7946 0958",
        "+61 2 5550 1234",
        "not-a-number"
      ]
    },
    "text": {
      "title": "Text",
      "type": "string",
      "editor": "textarea",
      "description": "For phone_extract (find numbers in text) or barcode payload."
    },
    "country": {
      "title": "Default country",
      "type": "string",
      "editor": "textfield",
      "description": "ISO country for national-format phone numbers, for example US.",
      "prefill": "US"
    },
    "number": {
      "title": "Document number",
      "type": "string",
      "editor": "textfield",
      "description": "Invoice or receipt number."
    },
    "date": {
      "title": "Date",
      "type": "string",
      "editor": "textfield",
      "description": "Invoice or receipt date, YYYY-MM-DD."
    },
    "due_date": {
      "title": "Due date",
      "type": "string",
      "editor": "textfield",
      "description": "Payment due date, YYYY-MM-DD."
    },
    "currency": {
      "title": "Currency",
      "type": "string",
      "editor": "textfield",
      "description": "ISO currency code, for example USD."
    },
    "seller": {
      "title": "Seller",
      "type": "object",
      "editor": "json",
      "description": "Seller block, for example name, address, email, phone, tax_id."
    },
    "buyer": {
      "title": "Buyer",
      "type": "object",
      "editor": "json",
      "description": "Buyer block, for example name, address, email, tax_id."
    },
    "items": {
      "title": "Line items",
      "type": "array",
      "editor": "json",
      "description": "Array of description, quantity, unit_price, and optional tax_rate."
    },
    "tax_rate": {
      "title": "Tax rate",
      "type": "number",
      "editor": "number",
      "description": "Percent, applied to items without their own tax_rate."
    },
    "type": {
      "title": "Barcode type",
      "type": "string",
      "editor": "textfield",
      "description": "For barcode_svg, for example code128 or ean13."
    },
    "crypto": {
      "title": "Payment block",
      "type": "object",
      "editor": "json",
      "description": "Optional network, token, address and amount for a payment URI or QR on the PDF."
    }
  },
  "required": [
    "mode"
  ]
}

